from collections import Counter
def solve(g):
    H,W=len(g),len(g[0])
    seen=[[False]*W for _ in range(H)]
    objs=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg2 and not seen[i][j]:
                col=g[i][j]; st=[(i,j)]; comp=set(); seen[i][j]=True
                while st:
                    r,c=st.pop(); comp.add((r,c))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        rr,cc=r+dr,c+dc
                        if 0<=rr<H and 0<=cc<W and not seen[rr][cc] and g[rr][cc]==col:
                            seen[rr][cc]=True; st.append((rr,cc))
                objs.append((col,comp))
    objs.sort(key=lambda o:len(o[1]))
    bg2=Counter(v for row in g for v in row).most_common(1)[0][0]
    mc,_=objs[0]; S=frozenset(objs[1][1])
    mr,mc=list(mc)[0]
    rs=[p[0] for p in S]; cs=[p[1] for p in S]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    dirs=[(r1-r0,c1-c0),(r1-r0,-(c1-c0)),(-(r1-r0),c1-c0),(-(r1-r0),-(c1-c0))]
    best=None
    for dr,dc in dirs:
        tot=set(); kp=1
        while True:
            cp={(r+dr*kp,c+dc*kp) for r,c in S}
            if any(not(0<=x<H and 0<=y<W) for x,y in cp): break
            tot|=cp; kp+=1
        if len(tot)> (len(best[0]) if best else 0): best=(dr,dc,tot)
    dr,dc,tot=best
    out=[row[:] for row in g]
    for i,j in tot:
        if 0<=i<H and 0<=j<W: out[i][j]=mc
    return out
